+                window * WAVEFORM_PEAK_LANES - 1,
+                window * WAVEFORM_PEAK_LANES,
+                window * WAVEFORM_PEAK_LANES + 1,
+                32_768 * usize::from(channels),
+            ] {
+                let blocks: Vec<&[f32]> = samples.chunks(block_len).collect();
+                assert_peak_bits(
